mapper.update:
update sup_server
server_name = #{fields.assetName}, server_address = #{fields.ipAddress}, ssh_port = #{fields.sshPort}, os_type = #{fields.osType}, status = #{fields.status}, remark = #{fields.remark}, equipment_room = #{fields.equipmentRoom}, cabinet_no = #{fields.cabinetNo}, rack_u_start = #{fields.rackUStart}, rack_u_end = #{fields.rackUEnd}, os_password_cipher = #{fields._legacyCipher}, os_username = #{fields._legacyUsername}, update_by = #{actor}, update_time = #{now}
where server_id = #{id} and site_id = #{siteId}

update sup_hardware_asset
asset_name = #{fields.assetName}, ip_address = #{fields.ipAddress}, manage_ip = #{fields.manageIp}, manufacturer = #{fields.manufacturer}, asset_model = #{fields.assetModel}, login_username = #{fields.loginUsername}, network_env = #{fields.networkEnv}, mac_address = #{fields.macAddress}, serial_no = #{fields.serialNo}, owner_org = #{fields.ownerOrg}, owner_contact = #{fields.ownerContact}, channel_count = #{fields.channelCount}, output_type = #{fields.outputType}, terminal_type = #{fields.terminalType}, department = #{fields.department}, use_location = #{fields.useLocation}, switch_level = #{fields.switchLevel}, port_count = #{fields.portCount}, uplink_device = #{fields.uplinkDevice}, vlan_info = #{fields.vlanInfo}, gateway_mode = #{fields.gatewayMode}, gateway_direction = #{fields.gatewayDirection}, gateway_bandwidth = #{fields.gatewayBandwidth}, security_zone = #{fields.securityZone}, status = #{fields.status}, remark = #{fields.remark}, equipment_room = #{fields.equipmentRoom}, cabinet_no = #{fields.cabinetNo}, rack_u_start = #{fields.rackUStart}, rack_u_end = #{fields.rackUEnd}, login_password_cipher = #{fields._passwordCipher}, update_by = #{actor}, update_time = #{now}
where asset_id = #{id} and site_id = #{siteId}

update sup_server_credential
set username = #{username}, password_cipher = #{cipher}, update_by = #{actor}, update_time = #{now}
where credential_id = #{credentialId} and server_id = #{serverId}
